<template>
  <div class="app-container">
    <h2>作业评阅</h2>
    <el-alert title="在线文本作业：学生提交后，教师选择文字添加批注并保存评分。" type="info" :closable="false" />
    <div class="toolbar"><el-button v-if="teacherClasses.length" type="primary" @click="showCreate=true">发布作业</el-button><el-button @click="load">刷新</el-button></div>
    <el-table :data="assignments" highlight-current-row @current-change="chooseAssignment">
      <el-table-column prop="title" label="作业" /><el-table-column prop="class_name" label="班级" width="140" /><el-table-column prop="deadline" label="截止时间" width="180" /><el-table-column label="状态" width="120"><template slot-scope="scope">{{ status(scope.row) }}</template></el-table-column>
    </el-table>
    <div v-if="current" class="detail">
      <h3>{{ current.title }} <el-button v-if="isTeacher" type="danger" size="mini" plain @click="deleteAssignment">删除作业</el-button></h3><p class="pre">{{ current.description }}</p>
      <template v-if="isTeacher">
        <div class="review"><div class="students"><h4>已提交学生（{{ submissions.length }}）</h4><div v-for="s in submissions" :key="s.id" class="student" :class="{selected: paper && paper.id===s.id}" @click="openPaper(s)">{{ s.nick_name }} <small>{{ s.returned_at ? '已打回' : s.graded_at ? '已批改' : '待批改' }}</small></div></div>
          <div class="paper" v-if="paper"><h4>作业内容</h4><p>在下方选中文字后点击“添加批注”。</p><div ref="content" class="content" @mouseup="captureSelection"><span v-for="(part,i) in highlighted(paper.content, notes)" :key="i" :class="{marked:part.marked}">{{ part.text }}</span></div><el-button size="small" @click="addNote">添加批注</el-button><div v-for="(note,i) in notes" :key="i" class="note"><b>“{{ note.quote }}”</b><el-input v-model="note.text" type="textarea" placeholder="填写批注" /><el-button type="text" @click="notes.splice(i,1)">删除</el-button></div><el-alert v-if="paper.returned_at" :title="'已打回：' + paper.return_reason" type="warning" :closable="false" /><div class="grade"><span>分数：</span><el-input-number v-model="score" :min="0" :max="100" :precision="2" /><el-input v-model="comment" type="textarea" placeholder="填写总体评语" :rows="3" /><el-button type="primary" :disabled="!!paper.returned_at" @click="saveGrade">保存批改</el-button><el-button type="warning" :disabled="!!paper.returned_at" @click="returnPaper">打回作业</el-button></div></div><div v-else class="paper empty">请选择左侧学生查看作业</div></div>
      </template>
      <template v-else><h4>我的作业</h4><el-alert v-if="mine && mine.returned_at" :title="'作业已打回，请修改后重新提交。原因：' + mine.return_reason" type="warning" :closable="false" /><el-input v-model="myContent" type="textarea" :rows="12" placeholder="在这里输入作业内容" /><el-button class="toolbar" type="primary" @click="submit">提交作业</el-button><p>重新提交会清除原有批改结果。</p><div v-if="mine && mine.graded_at"><h4>教师批改：{{ mine.score }} 分</h4><div class="content"><span v-for="(part,i) in highlighted(mine.content, myNotes)" :key="i" :class="{marked:part.marked}">{{ part.text }}</span></div><p class="pre">{{ mine.comment }}</p><div v-for="(note,i) in myNotes" :key="i" class="note"><b>“{{ note.quote }}”</b><p class="pre">{{ note.text }}</p></div></div><p v-else-if="mine && !mine.returned_at">已提交，等待教师批改。</p></template>
    </div>
    <el-dialog title="发布作业" :visible.sync="showCreate" width="540px"><el-form label-width="85px"><el-form-item label="班级"><el-select v-model="form.classId" placeholder="选择班级"><el-option v-for="c in teacherClasses" :key="c.class_id" :value="c.class_id" :label="c.name" /></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title" maxlength="200" /></el-form-item><el-form-item label="作业要求"><el-input v-model="form.description" type="textarea" :rows="4" /></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="form.deadline" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" placeholder="可不设置" /></el-form-item></el-form><span slot="footer"><el-button @click="showCreate=false">取消</el-button><el-button type="primary" @click="create">发布</el-button></span></el-dialog>
  </div>
</template>
<script>
import request from '@/utils/request'
const api = (url, method='get', data) => request({ url: '/homework' + url, method, data })
export default {
  data() { return { classes: [], assignments: [], current: null, submissions: [], paper: null, mine: null, myContent: '', notes: [], selection: null, score: 0, comment: '', showCreate: false, form: { classId: '', title: '', description: '', deadline: null } } },
  computed: { teacherClasses() { return this.classes.filter(c => c.role === 'teacher') }, isTeacher() { return this.current && this.teacherClasses.some(c => c.class_id === this.current.class_id) && String(this.current.teacher_id) === String(this.$store.getters.id) }, myNotes() { return this.parse(this.mine && this.mine.annotations) } },
  created() { this.load() },
  methods: {
    parse(value) { try { const result = JSON.parse(value || '[]'); return Array.isArray(result) ? result : [] } catch (e) { return [] } },
    async load() { const [c,a] = await Promise.all([api('/classes'),api('/assignments')]); this.classes=c.data || []; this.assignments=a.data || [] },
    status(row) { if (this.teacherClasses.some(c => c.class_id===row.class_id) && String(row.teacher_id)===String(this.$store.getters.id)) return '教师'; return row.returned_at ? '已打回' : row.graded_at ? '已批改' : row.submission_id ? '已提交' : '未提交' },
    async chooseAssignment(row) { this.current=row; this.paper=null; this.mine=null; this.submissions=[]; if (!row) return; if (this.isTeacher) { const r=await api('/assignments/'+row.id+'/submissions'); this.submissions=r.data || [] } else { const r=await api('/assignments/'+row.id+'/mine'); this.mine=r.data; this.myContent=this.mine ? this.mine.content : '' } },
    async create() { await api('/assignments','post',this.form); this.$message.success('作业已发布'); this.showCreate=false; this.form={classId:'',title:'',description:'',deadline:null}; await this.load() },
    async submit() { await this.$confirm('重新提交将清除该作业已有的评分和批注，确定提交吗？','提交作业'); await api('/assignments/'+this.current.id+'/submit','post',{content:this.myContent}); this.$message.success('提交成功'); await this.load(); await this.chooseAssignment(this.assignments.find(a=>a.id===this.current.id)) },
    async openPaper(s) { const r=await api('/submissions/'+s.id); this.paper=r.data; this.notes=this.parse(this.paper.annotations); this.score=this.paper.score === null ? 0 : Number(this.paper.score); this.comment=this.paper.comment || ''; this.selection=null },
    highlighted(content, notes) { const boundaries=new Set([0,content.length]); notes.forEach(n=>{ if(Number.isInteger(n.start) && Number.isInteger(n.end) && n.start>=0 && n.end<=content.length && n.start<n.end) { boundaries.add(n.start); boundaries.add(n.end) } }); const points=[...boundaries].sort((a,b)=>a-b); return points.slice(0,-1).map((start,i)=>({text:content.slice(start,points[i+1]),marked:notes.some(n=>n.start<=start && n.end>=points[i+1])})) },
    captureSelection() { const sel=window.getSelection(), root=this.$refs.content; if (!sel || !sel.rangeCount || !root.contains(sel.anchorNode) || !root.contains(sel.focusNode)) { this.selection=null; return } const range=sel.getRangeAt(0); const before=range.cloneRange(); before.selectNodeContents(root); before.setEnd(range.startContainer,range.startOffset); const start=before.toString().length, quote=range.toString(); this.selection=quote ? {start,end:start+quote.length,quote} : null },
    addNote() { if (!this.selection) return this.$message.warning('请先选中作业中的文字'); this.notes.push({...this.selection,text:''}); this.selection=null },
    async deleteAssignment() { try { await this.$confirm('删除后师生将无法查看该作业及其提交，确定删除吗？','删除作业',{type:'warning'}); } catch(e) { return } await api('/assignments/'+this.current.id,'delete'); this.current=null; this.paper=null; await this.load(); this.$message.success('作业已删除') },
    async returnPaper() { let result; try { result=await this.$prompt('请输入打回原因，学生可以看到并修改后重新提交。打回将清除已有分数、评语和批注。','打回作业',{inputType:'textarea',inputValidator:v => !!v && !!v.trim() && v.trim().length<=2000 || '请填写不超过2000字的原因'}); } catch(e) { return } await api('/submissions/'+this.paper.id+'/return','put',{reason:result.value,version:this.paper.version}); this.$message.success('已打回，等待学生重新提交'); const id=this.paper.id; await this.chooseAssignment(this.current); await this.openPaper({id}) },
    async saveGrade() { if (this.notes.some(n=>!n.text.trim())) return this.$message.warning('请填写所有批注'); await api('/submissions/'+this.paper.id+'/grade','put',{score:this.score,comment:this.comment,annotations:JSON.stringify(this.notes),version:this.paper.version}); this.$message.success('批改已保存'); const id=this.paper.id; await this.chooseAssignment(this.current); await this.openPaper({id}) }
  }
}
</script>
<style scoped>
.toolbar{margin:16px 0}.detail{margin-top:25px}.pre,.content{white-space:pre-wrap;word-break:break-word}.review{display:flex;gap:20px;border:1px solid #e5e8ef;min-height:420px}.students{width:220px;flex:none;border-right:1px solid #e5e8ef;padding:15px}.student{cursor:pointer;padding:12px;border-radius:4px}.student:hover,.selected{background:#ecf5ff}.student small{float:right;color:#909399}.paper{padding:15px;flex:1;min-width:0}.empty{color:#909399}.content{padding:20px;background:#f7f9fc;border:1px solid #e5e8ef;min-height:180px;margin-bottom:12px}.marked{background:#ffe080}.note{background:#fff9eb;padding:12px;margin:10px 0}.grade{margin-top:20px}.grade .el-textarea{margin:15px 0}
</style>
